INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ASP ausschließlich eine clientseitige Technologie?', 2, '[{"text": "Nein", "correct": true, "because": "Serverseitig ausgeführt"}, {"text": "Ja", "correct": false, "because": "Läuft auf dem Server"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit ASP?', 3, '[{"text": "Dynamische Webseiten erstellen", "correct": true, "because": "Serverseitige Logik"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Nicht primär"}, {"text": "Hardware steuern", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu ASP?', 5, '[{"text": "Serverseitiges Skripting", "correct": true, "because": "Kern der Technologie"}, {"text": "VBScript-Unterstützung", "correct": true, "because": "Häufig verwendet"}, {"text": "Clientseitige GUI", "correct": false, "because": "Serverseitig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) ASP läuft auf IIS-Servern. b) Es ist plattformunabhängig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Primär für Windows/IIS"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung von ASP?', 4, '[{"text": "Serverkonfiguration", "correct": false, "because": "Entscheidend für Betrieb"}, {"text": "Skriptsprache", "correct": false, "because": "Bestimmt Funktionalität"}, {"text": "Bürogestaltung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ASP Datenbankzugriff unterstützt?', 2, '[{"text": "Ja", "correct": true, "because": "ADO für Datenbanken"}, {"text": "Nein", "correct": false, "because": "Kernfunktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Sprache wird typischerweise mit ASP verwendet?', 3, '[{"text": "VBScript", "correct": true, "because": "Standard in klassischem ASP"}, {"text": "Python", "correct": false, "because": "Nicht üblich"}, {"text": "Java", "correct": false, "because": "Andere Technologie"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Entwicklung mit ASP?', 5, '[{"text": "Serverseitige Logik", "correct": true, "because": "Dynamische Inhalte"}, {"text": "Datenbankintegration", "correct": true, "because": "Häufig genutzt"}, {"text": "Hardwaresteuerung", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) ASP ist eine Microsoft-Technologie. b) Es ist komplett veraltet. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "ASP.NET weiterentwickelt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei ASP unwichtig?', 4, '[{"text": "Serverumgebung", "correct": false, "because": "Notwendig für Betrieb"}, {"text": "Skriptausführung", "correct": false, "because": "Kernmechanismus"}, {"text": "Clientseitige Hardware", "correct": true, "because": "Serverfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Läuft ASP auf Apache-Servern?', 2, '[{"text": "Nein", "correct": true, "because": "Primär IIS"}, {"text": "Ja", "correct": false, "because": "Microsoft-Technologie"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ASP?', 4, '[{"text": "Dynamische Webinhalte", "correct": true, "because": "Serverseitige Verarbeitung"}, {"text": "Einfache Datenbankanbindung", "correct": true, "because": "ADO-Unterstützung"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ASP nur für kleine Projekte geeignet ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Skalierbar"}, {"text": "Ja", "correct": false, "because": "Vielseitig einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei ASP?', 3, '[{"text": "Serverseitige Logik", "correct": true, "because": "Hauptmerkmal"}, {"text": "Clientseitiges Design", "correct": false, "because": "Sekundär"}, {"text": "Hardware-Optimierung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) ASP unterstützt dynamische Inhalte. b) Es ist plattformunabhängig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Plattformgebunden (Windows)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat klassisches ASP?', 5, '[{"text": "Eingeschränkte Skalierbarkeit", "correct": true, "because": "Verglichen mit ASP.NET"}, {"text": "Abhängigkeit von IIS", "correct": true, "because": "Windows-spezifisch"}, {"text": "Hohe Flexibilität", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei ASP unwichtig?', 3, '[{"text": "Datenbankzugriff", "correct": false, "because": "Häufig genutzt"}, {"text": "Serverseitige Verarbeitung", "correct": false, "because": "Kernfunktion"}, {"text": "Clientseitige Skripte", "correct": true, "because": "Serverfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ASP mit JavaScript genutzt werden?', 3, '[{"text": "Ja", "correct": true, "because": "Alternative zu VBScript"}, {"text": "Nein", "correct": false, "because": "Unterstützt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ASP Datenbanken integriert?', 2, '[{"text": "Ja", "correct": true, "because": "ADO ermöglicht Zugriff"}, {"text": "Nein", "correct": false, "because": "Kernfunktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologie wähle ich für dynamische ASP-Seiten?', 4, '[{"text": "VBScript", "correct": true, "because": "Klassische Wahl"}, {"text": "HTML allein", "correct": false, "because": "Statisch"}, {"text": "CSS", "correct": false, "because": "Design, nicht Logik"}]');
